package in.paisa.personal;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.Build;
import org.json.*;
import java.time.*;
import java.util.*;

public class Reminders extends BroadcastReceiver {
 @Override public void onReceive(Context context,Intent intent){if(intent==null||!Arrays.asList("in.paisa.REMIND",Intent.ACTION_BOOT_COMPLETED,Intent.ACTION_MY_PACKAGE_REPLACED,Intent.ACTION_TIMEZONE_CHANGED).contains(intent.getAction()))return;final PendingResult result=goAsync();new Thread(()->{try{check(context);schedule(context);}finally{result.finish();}},"paisa-reminders").start();}
 public static void schedule(Context c){try{AlarmManager manager=c.getSystemService(AlarmManager.class);PendingIntent pi=PendingIntent.getBroadcast(c,7001,new Intent(c,Reminders.class).setAction("in.paisa.REMIND"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);LocalDateTime time=LocalDate.now().atTime(9,0);if(time.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli()<=System.currentTimeMillis())time=time.plusDays(1);manager.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,time.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli(),pi);}catch(Exception ignored){}}
 public static void check(Context c){if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;try(Store store=new Store(c)){JSONObject cfg=store.settings();if(!cfg.optBoolean("reminders",true))return;JSONObject stamps=cfg.optJSONObject("alertStamps");if(stamps==null)stamps=new JSONObject();List<String> messages=new ArrayList<>();LocalDate today=LocalDate.now();JSONArray bills=store.bills(),entries=store.entries(),subs=store.subscriptions();
   for(int i=0;i<bills.length();i++){JSONObject b=bills.getJSONObject(i);long remaining=Ledger.remaining(b,entries);if(remaining<=0)continue;long days=LocalDate.parse(b.getString("due")).toEpochDay()-today.toEpochDay();String stage=days==0?"today":days>0&&days<=3?"soon":days<0&&(-days)%7==0?"overdue":"";String key="bill:"+b.optString("id")+":"+b.optString("due")+":"+stage;if(!stage.isEmpty()&&!stamps.has(key)){messages.add(b.optString("name")+" · ₹"+java.math.BigDecimal.valueOf(remaining,2).stripTrailingZeros().toPlainString()+" · "+(days==0?"due today":days<0?"overdue":"due "+b.optString("due")));stamps.put(key,today.toString());}}
   for(int i=0;i<subs.length();i++){JSONObject s=subs.getJSONObject(i);if(!s.optBoolean("active",true))continue;long days=LocalDate.parse(s.getString("nextDue")).toEpochDay()-today.toEpochDay();String stage=days==0?"today":days>0&&days<=2?"soon":"",key="sub:"+s.optString("id")+":"+s.optString("nextDue")+":"+stage;if(!stage.isEmpty()&&!stamps.has(key)){messages.add(s.optString("name")+" renewal · "+s.optString("nextDue"));stamps.put(key,today.toString());}}
   long[] cycle=Ledger.cycle(System.currentTimeMillis(),cfg.optInt("cycleStartDay",1));long spent=0;Map<String,Long> categories=new HashMap<>();for(int i=0;i<entries.length();i++){JSONObject e=entries.getJSONObject(i);if(!Ledger.active(e)||e.optLong("date")<cycle[0]||e.optLong("date")>=cycle[1])continue;String k=e.optString("kind");if(k.equals("expense")||k.equals("refund")){long n=e.optLong("amount")*(k.equals("refund")?-1:1);spent+=n;String category=e.optString("category");categories.put(category,categories.getOrDefault(category,0L)+n);}}
   JSONObject limits=cfg.optJSONObject("categoryBudgets");if(limits==null)limits=new JSONObject();Map<String,Long> budgets=new LinkedHashMap<>();budgets.put("Monthly budget",cfg.optLong("monthBudget"));for(Iterator<String> it=limits.keys();it.hasNext();){String key=it.next();budgets.put(key,limits.optLong(key));}for(Map.Entry<String,Long> b:budgets.entrySet()){long limit=b.getValue(),used=b.getKey().equals("Monthly budget")?spent:categories.getOrDefault(b.getKey(),0L);int stage=limit>0&&used>=limit?100:limit>0&&used*100>=limit*80?80:0;String key="budget:"+cycle[0]+":"+b.getKey()+":"+stage;if(stage>0&&!stamps.has(key)){messages.add(b.getKey()+" · "+stage+"% used");stamps.put(key,today.toString());}}
   if(messages.isEmpty())return;NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("reminders","Bills, subscriptions & budgets",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(c,7100,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.InboxStyle style=new Notification.InboxStyle();for(String line:messages)style.addLine(line);Notification n=new Notification.Builder(c,"reminders").setSmallIcon(R.drawable.ic_paisa).setContentTitle("Paisa · "+messages.size()+" updates").setContentText(messages.get(0)).setStyle(style).setVisibility(Notification.VISIBILITY_PRIVATE).setContentIntent(open).setAutoCancel(true).build();nm.notify(7100,n);cfg.put("alertStamps",stamps);store.setSettings(cfg);
  }catch(Exception ignored){}
 }
}
